INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 7, 'theory', 'Quiz: window and divide and conquer');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 7, 0, 'Why does a sliding window algorithm run in linear time even though there is another loop inside the loop?', '["The inner loop always runs once", "Each element enters the window once and leaves at most once, so there are at most 2n boundary moves in total", "The inner loop runs in parallel", "The interpreter optimizes nested loops"]', 1, 'We count not the depth of the loops but the total number of boundary moves: the right one only goes forward, and so does the left one. So the total is about 2n.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 7, 1, 'For which problem will a sliding window that tightens the left boundary give a wrong answer?', '["The longest substring without repeats", "The shortest subarray with a sum of at least the target, when the array contains negative numbers", "The maximum sum of k consecutive elements", "Anagrams in a string"]', 1, 'With negative numbers, expanding the window does not guarantee that the sum grows, nor shrinking that it falls: monotonicity is lost. Here you need prefix sums and a hash table.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 7, 2, 'What does the monotonic queue store when finding the maximum in a window?', '["All elements of the window in order of arrival", "Indices of elements whose values decrease; the head holds the window maximum", "Only the current maximum", "The sorted elements of the window"]', 1, 'A new element pops smaller ones from the end: they expire sooner and will never become maxima. Indices that have left the window are removed from the head.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 7, 3, 'A problem splits into two halves, and combining the results costs linear time. What is the overall complexity?', '["O(n)", "O(n log n)", "O(n²)", "O(log n)"]', 1, 'The recursion tree has log n levels, and the total combining work on each is about n, so n log n in all, like merge sort.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 7, 4, 'When is divide and conquer a poor choice?', '["When the subproblems are independent", "When the subproblems overlap and the same ones are computed many times, so memoization (dynamic programming) is needed", "When combining costs linear time", "When the problem can be split in half"]', 1, 'Independence of the subproblems is the key condition. Overlapping subproblems without memoization are recomputed exponentially many times.');
